(a)−H₂(b) : 0≤b<a≤1/2, Γ(a,b) > 1−2δ}", "standard_concept": "κ_H", "matches_standard": "unclear", "note": "κ_H is not in the excerpt. The set is nonempty (a=1/2, b=0) and bounded below by 0, so sInf is genuine."}, {"decl": "Johnson.spectralLimit", "line": 103, "plain": "Λ_{α,β,γ}(u) as in (6), with σ=ζ and η=ξ", "standard_concept": "Λ in eq. (6)", "matches_standard": "partly", "note": "The formula transcribes (6). The definitions of z, m, ζ, ξ (as 1−2u, 1−2α, 1−2β−2γ, 1−2α+2β−2γ) are not in the excerpt."}, {"decl": "Johnson.asymptoticThreshold", "line": 113, "plain": "1 − δ/(2α(1−α))", "standard_concept": "RHS of (7)", "matches_standard": "yes", "note": ""}, {"decl": "Johnson.shellRate", "line": 120, "plain": "1 − H₂(α) + H₂(u) − αH₂(β/α) − (1−α)H₂(γ/(1−α))", "standard_concept": "objective of (8)", "matches_standard": "yes", "note": ""}, {"decl": "Johnson.AsymptoticParameters", "line": 124, "plain": "the following parameter ranges:
- 0<δ<1/2 and δ/2<α<1/2;
- 0≤β<α/2 and 0≤γ<(1−α)/2;
- β+γ<u<α;
- u<α−β+γ and u<1−α+β−γ", "standard_concept": "ranges (4)–(5)", "matches_standard": "unclear", "note": "Ranges (4)–(5) are not in the excerpt."}, {"decl": "Johnson.variationalRate", "line": 149, "plain": "κ_CW(δ) = inf of shellRate over D_δ", "standard_concept": "κ_CW (8)", "matches_standard": "partly", "note": "Correct modulo the unverified ranges. All denominators are positive under the constraints."}, {"decl": "Johnson.combinedVariationalRate", "line": 151, "plain": "κ_bin(δ) = min{κ_H, κ_CW}", "standard_concept": "κ_bin", "matches_standard": "yes", "note": ""}, {"decl": "Johnson.mrrwRate", "line": 165, "plain": "M₂(δ) = min_{0≤r≤1−2δ} 1 + g(r²) − g(r²+2δr+2δ), with g(v)=H₂((1−√(1−v))/2)", "standard_concept": "second MRRW bound", "matches_standard": "yes", "note": "The argument is ≤1 on the range, and the r=1−2δ endpoint gives M₁."}], "lean_claims": [{"theorem": "Hamming.binaryRate_lt_classicalRate", "line": 65, "plain": "For 0<δ<1/2, R₂(δ) < M₁(δ)."}, {"theorem": "Hamming.exists_binaryRate_improvement", "line": 70, "plain": "For 0<δ<1/2, there is ε>0 with R₂(δ) ≤ M₁(δ) − ε."}, {"theorem": "Johnson.binaryRate_le_combinedVariationalRate", "line": 168, "plain": "For 0<d<1/2, R₂(d) ≤ min{κ_H(d), κ_CW(d)}."}, {"theorem": "Johnson.binaryRate_lt_mrrw", "line": 173, "plain": "For 0<d<1/2, R₂(d) < M₂(d)."}, {"theorem": "Johnson.exists_binaryRate_mrrw_improvement", "line": 178, "plain": "For 0<d<1/2, there is e>0 with R₂(d) ≤ M₂(d) − e."}, {"theorem": "MRRW.strict_mrrw2", "line": 187, "plain": "For 0<δ<1/2, κ_bin(δ) < M₂(δ)."}], "paper_claims": [{"ref": "Theorem 1.1", "plain": "For every fixed 0<δ<1/2, R₂(δ) ≤ κ_bin(δ) < M₂(δ)."}, {"ref": "Theorem 2.3 / Proposition 3.7 (mentioned)", "plain": "Positive harmonic degrees strictly improve M₁ and the classical constant-weight objective (statements not in excerpt)."}, {"ref": "Theorem 1.2, Corollaries 1.3–1.4", "plain": "Spherical-code and sphere-packing results."}], "coverage": [{"paper_ref": "Theorem 1.1 (first inequality)", 